2	//   "Put two dates on each invoice. One for when it went out. One for when it is due. Show them
3	//    both."
4	//
5	// Each invoice now carries two dates: the date it WENT OUT (issued) and the date it is DUE. Both are
6	// SHOWN on the project's detail page, each behind its own stable anchor inside the invoice's row:
7	//   - invoice-issued — when the invoice went out
8	//   - invoice-due    — when the invoice is due
9	// The two are distinct values in distinct cells (not the same date shown twice, not swapped), and
10	// each invoice shows ITS OWN pair.
11	//
12	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
13	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
14	// `invoices` honours { id, amount, projectId, status, issuedDate, dueDate }.
15	import { test, expect, type Page, type Locator } from '@playwright/test';
16	import { resetAndSeed } from '../support/seed';
17	
18	const issuedOf = (page: Page, id: number): Locator =>
19	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-issued');
20	const dueOf = (page: Page, id: number): Locator =>
21	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-due');
22	
23	// The request names no date format, so the assertions bind to WHICH date a cell shows rather than to
24	// one presentation. A date may be rendered ISO (2019-03-14), US-style (3/14/2019) or long
25	// ("March 14, 2019") — in every common rendering the four-digit year and the day-of-month both
26	// appear, so a cell "shows" a given date when it contains that date's year AND its day. The four
27	// dates seeded below are chosen with four DISTINCT years (2019/2020/2021/2022) and four distinct day
28	// numbers, none a substring of another or of any month/year token — so requiring a cell to carry its
29	// own year and NOT any of the other three years pins it to exactly one of the four dates. That is
30	// what proves the issued and due cells are not the same value, not swapped, and not borrowed from the
31	// other invoice.
32	type D = { iso: string; year: string; day: string };
33	const d = (iso: string): D => {
34	  const [year, , day] = iso.split('-');
35	  return { iso, year, day: String(Number(day)) };
36	};
37	
38	async function expectShows(cell: Locator, want: D, others: D[]): Promise<void> {
39	  await expect(cell).toBeVisible();
40	  await expect(cell).toContainText(want.year);
41	  await expect(cell).toContainText(want.day);
42	  for (const other of others) {
43	    if (other.year !== want.year) {
44	      await expect(cell).not.toContainText(other.year);
45	    }
46	  }
47	}
48	
49	test.describe('Each invoice shows an issued date and a due date', () => {
50	  test('an invoice shows both dates, as distinct values in their own cells', async ({ page }) => {
51	    const issued = d('2019-03-14');
52	    const due = d('2020-07-28');
53	
54	    await resetAndSeed({
55	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
56	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
57	      invoices: [
58	        { id: 1, amount: 100, projectId: 1, status: 'UNPAID', issuedDate: issued.iso, dueDate: due.iso },
59	      ],
60	    });
61	
62	    await page.goto('/projects/1');
63	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
64	
65	    // Both dates are shown, each behind its own anchor.
66	    await expect(issuedOf(page, 1)).toBeVisible();
67	    await expect(dueOf(page, 1)).toBeVisible();
68	
69	    // The "went out" cell shows the issued date (2019) and NOT the due date (2020); the "due" cell
70	    // shows the due date (2020) and NOT the issued date (2019). So the two are distinct and not
71	    // swapped.
72	    await expectShows(issuedOf(page, 1), issued, [due]);
73	    await expectShows(dueOf(page, 1), due, [issued]);
74	  });
75	
76	  test('each invoice shows its OWN pair of dates', async ({ page }) => {
77	    const a = { issued: d('2019-03-14'), due: d('2020-07-28') };
78	    const b = { issued: d('2021-11-16'), due: d('2022-09-23') };
79	    const all = [a.issued, a.due, b.issued, b.due];
80	
81	    await resetAndSeed({
82	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
83	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
84	      invoices: [
85	        { id: 1, amount: 100, projectId: 1, status: 'UNPAID', issuedDate: a.issued.iso, dueDate: a.due.iso },
86	        { id: 2, amount: 250, projectId: 1, status: 'UNPAID', issuedDate: b.issued.iso, dueDate: b.due.iso },
