99	    // dates, so no row borrows another row's dates and no cell shows the wrong one of its pair.
100	    await expectShows(issuedOf(page, 1), a.issued, all);
101	    await expectShows(dueOf(page, 1), a.due, all);
102	    await expectShows(issuedOf(page, 2), b.issued, all);
103	    await expectShows(dueOf(page, 2), b.due, all);
104	  });
